# area: abstract_classes
# hypothesis: an ABC with an abstract property cannot be instantiated, and a class added with Shape.register is accepted at runtime but is not a nominal subtype for the checker.
from abc import ABC, abstractmethod
from typing import reveal_type


class Shape(ABC):
    @property
    @abstractmethod
    def sides(self) -> int: ...

    @abstractmethod
    def area(self) -> float: ...


class Square(Shape):
    def __init__(self, side: float) -> None:
        self.side = side

    @property
    def sides(self) -> int:
        return 4

    def area(self) -> float:
        return self.side * self.side


class Blob:
    sides = 0

    def area(self) -> float:
        return 0.0


Shape.register(Blob)


def build() -> None:
    try:
        Shape()  # expect-error: cannot instantiate abstract class
    except TypeError:
        print('abstract instantiation refused')


sq = Square(2.0)
bl = Blob()
reveal_type(sq.sides)  # int
reveal_type(sq.area())  # float
b: Shape = bl  # expect-error: Blob is not a Shape subclass
print(isinstance(bl, Shape), sq.area(), bl.area())
build()
print(sq.sides)
